def is_admin_page():
    return st.query_params.get("admin", "0") == "1"


def get_initial_interface_mode():
    mode = st.query_params.get("mode", "hotel").lower()
    if mode in ["ota", "app", "mobile"]:
        return "OTA界面"
    return "酒店官网界面"


def get_initial_ad_frequency():
    freq = st.query_params.get("adfreq", "3").lower()
    if freq in ["1", "one"]:
        return "广告出现1次"
    if freq in ["2", "two"]:
        return "广告出现2次"
    if freq in ["4", "four"]:
        return "广告出现4次"
    if freq in ["5", "five"]:
        return "广告出现5次"
    return "广告出现3次"


def init_state():
    defaults = {
        "participant_id": str(uuid.uuid4())[:8],
        "stage": "浏览首页",
        "interface_mode": get_initial_interface_mode(),
        "ad_frequency": get_initial_ad_frequency(),
        "selected_room": "",
        "room_price": 0,
        "check_in": date.today() + timedelta(days=7),
        "check_out": date.today() + timedelta(days=8),
        "guest_count": 1,
        "paid": False,
        "events": [],
        "survey_submitted": False,
        "ad_seen": 0,
        "ad_exposed_keys": [],
        "selected_hotel_name": HOTEL_CN,
        "selected_hotel_en": HOTEL_EN,
        "selected_hotel_score": "4.8",
        "selected_hotel_desc": "近商圈 · 设计型酒店 · 商务休闲皆宜",
        "selected_hotel_img": HOTEL_IMAGES[0],
        "selected_hotel_gallery": [HOTEL_IMAGES[1], HOTEL_IMAGES[2], HOTEL_IMAGES[3]],
    }
    for k, v in defaults.items():
        if k not in st.session_state:
            st.session_state[k] = v


init_state()


def now_china_time_str():
    return (datetime.utcnow() + timedelta(hours=8)).strftime("%Y-%m-%d %H:%M:%S")


def log_event(event_type, detail=""):
    st.session_state.events.append(
        {
            "time": now_china_time_str(),
            "participant_id": st.session_state.participant_id,
            "stage": st.session_state.stage,
            "event_type": event_type,
            "detail": detail,
        }
    )


def save_events_to_csv():
    """按固定字段保存行为日志。"""
    if not st.session_state.events:
        return
    file_exists = EVENT_PATH.exists()
    with EVENT_PATH.open("a", newline="", encoding="utf-8-sig") as f:
        writer = csv.DictWriter(f, fieldnames=EVENT_COLUMNS, extrasaction="ignore")
        if not file_exists:
            writer.writeheader()
        for event in st.session_state.events:
            writer.writerow({col: event.get(col, "") for col in EVENT_COLUMNS})
    st.session_state.events = []


def save_result_to_csv(result):
    """按固定字段保存问卷数据，避免不同版本字段不一致导致CSV损坏。"""
    row = {col: result.get(col, "") for col in DATA_COLUMNS}
    file_exists = DATA_PATH.exists()
    with DATA_PATH.open("a", newline="", encoding="utf-8-sig") as f:
        writer = csv.DictWriter(f, fieldnames=DATA_COLUMNS, extrasaction="ignore")
        if not file_exists:
            writer.writeheader()
        writer.writerow(row)


def reset_experiment():
    keep_params = dict(st.query_params)
    for key in list(st.session_state.keys()):
        del st.session_state[key]
    for k, v in keep_params.items():
        st.query_params[k] = v
    init_state()
    st.rerun()


def go_stage(stage):
    st.session_state.stage = stage
    log_event("go_stage", stage)


def next_stage():
    idx = STAGES.index(st.session_state.stage)
    if idx < len(STAGES) - 1:
        go_stage(STAGES[idx + 1])


def prev_stage():
    idx = STAGES.index(st.session_state.stage)
    if idx > 0:
        go_stage(STAGES[idx - 1])


def is_valid_date_range():
    return st.session_state.check_out > st.session_state.check_in


def show_date_error_if_needed():
    if not is_valid_date_range():
        st.error("离店日期必须晚于入住日期，请重新选择入住和离店时间。")
        return True
    return False


def nights_count():
    if not is_valid_date_range():
        return 0
    return max((st.session_state.check_out - st.session_state.check_in).days, 1)


def fixed_image(url, height=220, radius=16):
    st.markdown(
        f"""
        <div style="width:100%; height:{height}px; overflow:hidden; border-radius:{radius}px; background:#f3f4f6;">
            <img src="{url}" style="width:100%; height:100%; object-fit:cover; display:block;" />
        </div>
        """,
        unsafe_allow_html=True,
    )


def show_ad():
    st.markdown(
        f"""
        <div style="width:100%; margin:8px 0 14px 0;">
            <img src="{AD_IMAGE_DATA}" style="width:100%; max-width:none; height:auto; object-fit:contain; display:block; border-radius:12px; box-shadow:0 4px 14px rgba(0,0,0,.07);" />
        </div>
        """,
        unsafe_allow_html=True,
    )


def maybe_show_ad():
    if st.session_state.stage in AD_STAGE_MAP.get(st.session_state.ad_frequency, []):
        exposure_key = f"{st.session_state.stage}_{st.session_state.ad_frequency}"
        if exposure_key not in st.session_state.ad_exposed_keys:
            st.session_state.ad_seen += 1
            st.session_state.ad_exposed_keys.append(exposure_key)
            log_event("ad_exposed", f"第{st.session_state.ad_seen}次看到广告：{st.session_state.stage}")
        show_ad()


def total_price():
    return st.session_state.room_price * nights_count()


def show_steps():
    html = "<div class='steps'>"
    current_idx = STAGES.index(st.session_state.stage)
    for i, stage in enumerate(STAGES):
        cls = "step-on" if i <= current_idx else "step-off"
        html += f"<span class='{cls}'>{i + 1}. {stage}</span>"
    html += "</div>"
    st.markdown(html, unsafe_allow_html=True)


def back_button(label="返回上一步"):
    if STAGES.index(st.session_state.stage) > 0:
        if st.button(label, key=f"back_{st.session_state.stage}"):
            prev_stage()
            st.rerun()


