def radio_scale_7(label, key, hint="1 = 非常不同意    7 = 非常同意"):
    """7点量表。默认不选择；导出时未选择记为0。"""
    st.markdown(f"<div class='survey-question'>{label}</div>", unsafe_allow_html=True)
    st.caption(hint)
    value = st.radio(
        " ",
        options=[1, 2, 3, 4, 5, 6, 7],
        index=None,
        horizontal=True,
        key=key,
        label_visibility="collapsed",
    )
    return 0 if value is None else int(value)


def radio_scale_5(label, key, hint="请选择 1 - 5"):
    """5点次数回忆题。默认不选择；导出时未选择记为0。"""
    st.markdown(f"<div class='survey-question'>{label}</div>", unsafe_allow_html=True)
    st.caption(hint)
    value = st.radio(
        " ",
        options=[1, 2, 3, 4, 5],
        index=None,
        horizontal=True,
        key=key,
        label_visibility="collapsed",
    )
    return 0 if value is None else int(value)


def render_survey():
    hotel_header()
    show_steps()
    back_button("返回上一页查看")
    st.markdown("### 预订体验问卷")
    st.markdown("请根据刚才的网页浏览与预订体验回答以下问题。")

    ad_perceived_frequency = radio_scale_7(
        "1. 您认为在网页浏览中公益营销活动的展示频率如何？",
        "ad_perceived_frequency",
        hint="1 = 非常少    4 = 适度    7 = 非常多",
    )

    ad_recall_count = radio_scale_5(
        "2. 您是否还记得在刚才的网页中遇到过几次公益营销界面？",
        "ad_recall_count",
        hint="1 / 2 / 3 / 4 / 5",
    )

    ad_distracting = radio_scale_7("3. 当我看到这则广告时，我觉得它是：分散注意力的。", "ad_distracting")
    ad_disturbing = radio_scale_7("4. 当我看到这则广告时，我觉得它是：令人不安的。", "ad_disturbing")
    ad_forced = radio_scale_7("5. 当我看到这则广告时，我觉得它是：强制的。", "ad_forced")
    ad_interfering = radio_scale_7("6. 当我看到这则广告时，我觉得它是：干扰性的。", "ad_interfering")
    ad_obtrusive = radio_scale_7("7. 当我看到这则广告时，我觉得它是：侵扰性的。", "ad_obtrusive")
    ad_intrusive = radio_scale_7("8. 当我看到这则广告时，我觉得它是：侵入性的。", "ad_intrusive")
    ad_in_the_way = radio_scale_7("9. 当我看到这则广告时，我觉得它是：碍事的。", "ad_in_the_way")

    st.markdown("---")
    st.markdown("<div class='survey-question'>10. 您的出生年份？</div>", unsafe_allow_html=True)
    birth_year = st.number_input(
        " ",
        min_value=1940,
        max_value=date.today().year,
        value=2000,
        step=1,
        key="birth_year",
        label_visibility="collapsed",
    )

    st.markdown("<div class='survey-question'>11. 您的性别是</div>", unsafe_allow_html=True)
    gender = st.radio(
        " ",
        options=[1, 2],
        index=None,
        format_func=lambda x: "1 男" if x == 1 else "2 女",
        horizontal=True,
        key="gender",
        label_visibility="collapsed",
    )
    gender = 0 if gender is None else int(gender)

    if not st.session_state.survey_submitted:
        if st.button("提交问卷", type="primary"):
            result = {
                "submit_time": now_china_time_str(),
                "participant_id": st.session_state.participant_id,
                "interface_mode": st.session_state.interface_mode,
                "ad_frequency": st.session_state.ad_frequency,
                "ad_seen": st.session_state.ad_seen,
                "selected_hotel_name": st.session_state.get("selected_hotel_name", HOTEL_CN),
                "selected_room": st.session_state.selected_room,
                "room_price": st.session_state.room_price,
                "total_price": total_price(),
                "paid": st.session_state.paid,
                "ad_perceived_frequency": ad_perceived_frequency,
                "ad_recall_count": ad_recall_count,
                "ad_distracting": ad_distracting,
                "ad_disturbing": ad_disturbing,
                "ad_forced": ad_forced,
                "ad_interfering": ad_interfering,
                "ad_obtrusive": ad_obtrusive,
                "ad_intrusive": ad_intrusive,
                "ad_in_the_way": ad_in_the_way,
                "birth_year": birth_year,
                "gender": gender,
            }
            save_result_to_csv(result)
            save_events_to_csv()
            st.session_state.survey_submitted = True
            st.success("问卷已提交，感谢您的参与！数据已保存。")
            st.rerun()
    else:
        st.success("问卷已提交，感谢您的参与！数据已保存。")
        st.info("如需让下一位参与者在同一实验条件下继续测试，请点击下方按钮。")
        if st.button("开始下一位参与者测试", type="primary"):
            reset_experiment()


# =========================
# 页面分发与后台
# =========================

def render_ota_wrapper():
    stage = st.session_state.stage
    if stage == "浏览首页":
        render_ota_home()
    elif stage == "酒店详情":
        render_ota_detail()
    elif stage == "房型选择":
        render_ota_rooms()
    elif stage == "订单确认":
        render_ota_order()
    elif stage == "支付页面":
        render_ota_payment()
    elif stage == "完成问卷":
        render_survey()


def render_participant_app():
    stage = st.session_state.stage
    if st.session_state.interface_mode == "OTA界面":
        render_ota_wrapper()
        return

    if stage == "浏览首页":
        render_home()
    elif stage == "酒店详情":
        render_detail()
    elif stage == "房型选择":
        render_rooms()
    elif stage == "订单确认":
        render_order()
    elif stage == "支付页面":
        render_payment()
    elif stage == "完成问卷":
        render_survey()


def make_participant_url():
    mode = "ota" if st.session_state.interface_mode == "OTA界面" else "hotel"
    freq_map = {
        "广告出现1次": "1",
        "广告出现2次": "2",
        "广告出现3次": "3",
        "广告出现4次": "4",
        "广告出现5次": "5",
    }
    return f"?mode={mode}&adfreq={freq_map.get(st.session_state.ad_frequency, '3')}"



def safe_read_csv(path):
    """安全读取CSV。若旧测试数据列数不一致或文件损坏，不让后台崩溃。"""
    try:
        return pd.read_csv(path)
    except pd.errors.ParserError:
        try:
            return pd.read_csv(path, on_bad_lines="skip")
        except Exception:
            return None
    except Exception:
        return None


def render_admin_panel():
    st.markdown("<div class='main-title'>后台管理页面</div>", unsafe_allow_html=True)
    st.markdown("<div class='sub-title'>本页面用于设置实验条件、预览受试者页面，并下载实验数据。受试者默认不会看到这里。</div>", unsafe_allow_html=True)

    with st.sidebar:
        st.header("后台控制台")
        st.session_state.interface_mode = st.selectbox(
            "界面类型",
            ["酒店官网界面", "OTA界面"],
            index=["酒店官网界面", "OTA界面"].index(st.session_state.interface_mode),
        )
        st.session_state.ad_frequency = st.selectbox(
            "广告展示频率",
            list(AD_STAGE_MAP.keys()),
            index=list(AD_STAGE_MAP.keys()).index(st.session_state.ad_frequency),
        )

        st.divider()
        st.write("当前阶段：", st.session_state.stage)
        c1, c2 = st.columns(2)
        with c1:
            if st.button("上一步"):
                prev_stage()
                st.rerun()
        with c2:
            if st.button("下一步"):
                next_stage()
                st.rerun()

        if st.button("重置实验", type="secondary"):
            reset_experiment()

        st.divider()
        st.subheader("生成受试者链接")
        st.code(make_participant_url(), language="text")

    tab1, tab2, tab3 = st.tabs(["受试者页面预览", "数据下载", "使用说明"])

    with tab1:
        render_participant_app()

    with tab2:
        st.markdown("### 实验数据")
        if DATA_PATH.exists():
            df = safe_read_csv(DATA_PATH)
            if df is None:
                st.error("实验数据文件读取失败，通常是因为旧版本测试数据和新版字段不一致，或CSV文件被写坏。")
                if st.button("删除损坏的实验数据文件，重新开始收集", type="primary"):
                    DATA_PATH.unlink(missing_ok=True)
                    st.success("已删除损坏的数据文件，请重新刷新页面。")
                    st.rerun()
                st.stop()
            st.dataframe(df, use_container_width=True)
            st.download_button("下载实验结果 CSV", data=DATA_PATH.read_bytes(), file_name="ad_frequency_experiment_data.csv", mime="text/csv")

            delete_rows = st.multiselect("选择要删除的实验数据行号", options=list(df.index), format_func=lambda x: f"第{x + 1}行")
            c1, c2 = st.columns(2)
            with c1:
                if st.button("删除选中实验数据行", disabled=len(delete_rows) == 0):
                    df.drop(index=delete_rows).reset_index(drop=True).to_csv(DATA_PATH, index=False, encoding="utf-8-sig")
                    st.success("已删除选中的实验数据行。")
                    st.rerun()
            with c2:
                if st.button("清空全部实验数据", type="secondary"):
                    DATA_PATH.unlink(missing_ok=True)
                    st.success("已清空实验数据。")
                    st.rerun()
        else:
            st.info("目前还没有实验结果数据。")

        st.markdown("### 行为日志")
        if EVENT_PATH.exists():
            event_df = safe_read_csv(EVENT_PATH)
            if event_df is None:
                st.error("行为日志文件读取失败，通常是因为旧版本日志格式不一致或CSV文件被写坏。")
                if st.button("删除损坏的行为日志文件，重新开始记录", type="primary"):
                    EVENT_PATH.unlink(missing_ok=True)
                    st.success("已删除损坏的行为日志文件，请重新刷新页面。")
                    st.rerun()
                st.stop()
            st.dataframe(event_df, use_container_width=True)
            st.download_button("下载行为日志 CSV", data=EVENT_PATH.read_bytes(), file_name="ad_frequency_experiment_events.csv", mime="text/csv")
        else:
            st.info("目前还没有行为日志。")

    with tab3:
        st.markdown(
            """
            **受试者链接：** 普通网页链接，不带 `?admin=1`。  
            **后台链接：** 在网页链接后加 `?admin=1`。  

            数据字段已经按最终问卷固定为：
            `ad_perceived_frequency`, `ad_recall_count`, `ad_distracting`, `ad_disturbing`, `ad_forced`, `ad_interfering`, `ad_obtrusive`, `ad_intrusive`, `ad_in_the_way`, `birth_year`, `gender`。

            URL参数：
            - `mode=hotel` 或 `mode=ota`
            - `adfreq=1 / 2 / 3 / 4 / 5`

            示例：
            - `https://your-app.streamlit.app/?mode=hotel&adfreq=3`
            - `https://your-app.streamlit.app/?mode=ota&adfreq=5`
            """
        )


if is_admin_page():
    render_admin_panel()
else:
    render_participant_app()
